import { Stack, type Breakpoint } from '@mui/material';
import type { MuiColorType } from '@tui/core';
import type { FC } from 'react';
import { useContext, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import type { MxProps } from '.';
import { MODULE_NAME } from '../name';
import type {
  AppClassificationQualifier,
  AppClassificationState,
  AppClassificationValue
} from '../providers/AppClassificationProvider';
import { AppClassificationContext } from '../providers/AppClassificationProvider';
import type { AppClassificationBaseProps } from './AppClassificationBase';
import { AppClassificationBase } from './AppClassificationBase';
import { AppTLP, isAppTLPValue, type AppTLPValue } from './AppTLP';

const AppClassificationColors: { [key in AppClassificationState]: MuiColorType } = {
  u: 'green',
  pa: 'lightBlue',
  pb: 'lightBlue',
  pc: 'lightBlue',
  c: 'blue',
  s: 'red',
  ts: 'orange',
  loading: 'grey',
  error: 'red'
};

type AppClassificationProps = {
  variant?: 'filled' | 'text' | 'outlined';
  breakpoint?: Breakpoint;
  overwrite?: { value?: AppClassificationValue; qualifier?: AppClassificationQualifier; tlp?: AppTLPValue };
  mx?: MxProps;
};

export const AppClassification: FC<AppClassificationProps> = ({ variant, breakpoint, overwrite, mx }) => {
  const context = useContext(AppClassificationContext);
  const { i18n } = useTranslation(MODULE_NAME);

  const _value = (overwrite?.value?.toLowerCase() ||
    context?.value?.toLowerCase() ||
    'error') as AppClassificationState;

  const _qualifier = (overwrite?.qualifier?.toLowerCase() || context?.qualifier?.toLowerCase()) as
    | AppClassificationQualifier
    | undefined;

  const tlpValue = overwrite?.tlp?.toLowerCase() || context?.tlp?.toLowerCase();
  const _tlp = isAppTLPValue(tlpValue) ? tlpValue : undefined;

  const enClassiT = i18n.getFixedT('en', MODULE_NAME);
  const frClassiT = i18n.getFixedT('fr', MODULE_NAME);

  const qualifierText = useMemo(() => {
    if (!_qualifier) {
      return undefined;
    }

    return {
      short_qualifier_en: enClassiT(`classification.qualifiers.${_qualifier}.short`),
      short_qualifier_fr: frClassiT(`classification.qualifiers.${_qualifier}.short`),
      long_qualifier_en: enClassiT(`classification.qualifiers.${_qualifier}.long`),
      long_qualifier_fr: frClassiT(`classification.qualifiers.${_qualifier}.long`)
    };
  }, [_qualifier, enClassiT, frClassiT]);

  const configs: AppClassificationBaseProps = useMemo(
    () => ({
      short_text_en: enClassiT(`classification.${_value}.short`),
      short_text_fr: frClassiT(`classification.${_value}.short`),
      long_text_en: enClassiT(`classification.${_value}.long`),
      long_text_fr: frClassiT(`classification.${_value}.long`),
      ...qualifierText,
      color: AppClassificationColors[_value]
    }),
    [enClassiT, frClassiT, _value, qualifierText]
  );

  return _tlp ? (
    <Stack direction="row" alignItems="center">
      <AppClassificationBase {...configs} variant={variant} breakpoint={breakpoint} state={_value} mx={mx} />
      <AppTLP value={_tlp} mx={mx} />
    </Stack>
  ) : (
    <AppClassificationBase {...configs} variant={variant} breakpoint={breakpoint} state={_value} mx={mx} />
  );
};
