import { Security } from '@mui/icons-material';
import type { Breakpoint, Theme } from '@mui/material';
import { Chip, Skeleton, Typography, useMediaQuery, useTheme } from '@mui/material';
import type { MuiColorType } from '@tui/core';
import { useAppColor, useAppLanguage } from '@tui/core';
import type { FC } from 'react';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import type { MxProps } from '.';
import { MODULE_NAME } from '../name';
import type { AppClassificationState, AppClassificationValue } from '../providers/AppClassificationProvider';
import { AppClassificationValues } from '../providers/AppClassificationProvider';

export type AppClassificationBaseProps = {
  variant?: 'filled' | 'text' | 'outlined';
  state?: AppClassificationState | 'unsupported';
  breakpoint?: Breakpoint;
  short_text_en: string;
  short_text_fr: string;
  long_text_en: string;
  long_text_fr: string;
  short_qualifier_en?: string;
  short_qualifier_fr?: string;
  long_qualifier_en?: string;
  long_qualifier_fr?: string;
  color: MuiColorType;
  mx?: MxProps;
};

export const AppClassificationBase: FC<AppClassificationBaseProps> = ({
  variant,
  state,
  breakpoint = 'xl',
  short_text_en,
  short_text_fr,
  long_text_en,
  long_text_fr,
  short_qualifier_en,
  short_qualifier_fr,
  long_qualifier_en,
  long_qualifier_fr,
  color,
  mx
}) => {
  const theme = useTheme();
  const errorColor = useAppColor('red', 700, 300);
  const classiColor = useAppColor(color, 700, 300);
  const isLoading = state === 'loading';
  const _isBreakpoint = useMediaQuery((theme: Theme) => theme.breakpoints.down(breakpoint ?? 'xl'));
  const isBreakpoint = breakpoint !== null && _isBreakpoint;
  const { isEN } = useAppLanguage();
  const { t } = useTranslation(MODULE_NAME);

  const renderer = useMemo(() => {
    if (!state || AppClassificationValues.includes(state as AppClassificationValue)) {
      return 'classi';
    }
    return state;
  }, [state]);

  const sxProps = useMemo(() => {
    const _color = renderer === 'unsupported' ? errorColor : classiColor;
    if (variant === 'filled') {
      return {
        chip: {
          color: theme.palette.getContrastText(_color),
          bgcolor: !isLoading ? _color : null,
          borderColor: 'transparent',
          fontWeight: 600,

          borderRadius: 0
        },
        icon: {
          color: isLoading ? _color : theme.palette.getContrastText(_color),
          opacity: isLoading ? 0.5 : 1
        }
      };
    }

    if (variant === 'outlined') {
      return {
        chip: {
          color: _color,
          borderColor: _color,
          fontWeight: 600,

          borderRadius: 0
        },
        icon: {
          color: _color,
          opacity: isLoading ? 0.5 : 1
        }
      };
    }

    return {
      chip: {
        color: _color,
        borderColor: 'transparent',
        fontWeight: 600,

        borderRadius: 0
      },
      icon: {
        color: _color,
        opacity: isLoading ? 0.5 : 1
      }
    };
  }, [renderer, errorColor, classiColor, variant, isLoading, theme.palette]);

  const text = useMemo(() => {
    const classificationText = isBreakpoint
      ? isEN()
        ? short_text_en
        : short_text_fr
      : isEN()
        ? long_text_en
        : long_text_fr;
    const qualifierText = isBreakpoint
      ? isEN()
        ? short_qualifier_en
        : short_qualifier_fr
      : isEN()
        ? long_qualifier_en
        : long_qualifier_fr;

    if (!qualifierText) {
      return classificationText;
    }

    return `${classificationText}${qualifierText}`;
  }, [
    isBreakpoint,
    isEN,
    short_text_en,
    short_text_fr,
    long_text_en,
    long_text_fr,
    short_qualifier_en,
    short_qualifier_fr,
    long_qualifier_en,
    long_qualifier_fr
  ]);

  return (
    <Chip
      size="small"
      sx={{ ...sxProps.chip, ...(mx ?? {}), borderRadius: 0, fontWeight: 600 }}
      icon={<Security color="inherit" sx={sxProps.icon} />}
      variant="outlined"
      label={
        {
          classi: text,
          unsupported: isBreakpoint
            ? t('classification.state.unsupported.short').toUpperCase()
            : t('classification.state.unsupported.long').toUpperCase(),
          error: isBreakpoint
            ? t('classification.state.error.short').toUpperCase()
            : t('classification.state.error.long').toUpperCase(),
          loading: (
            <Skeleton variant="text" animation="wave" sx={{ minWidth: isBreakpoint ? 48 : 100 }}>
              <Typography>
                {isBreakpoint
                  ? t('classification.state.loading.short').toUpperCase()
                  : t('classification.state.loading.long').toUpperCase()}
              </Typography>
            </Skeleton>
          )
        }[renderer]
      }
    />
  );
};
